#ifndef SWGXR_RANGER_H
#define SWGXR_RANGER_H
#include "SwgxrPets.h"
#include "ConcealCommand.h"
#include "AreatrackCommand.h"
#include "server/zone/objects/tangible/threat/ThreatStates.h"
// Native item/command mechanics; gestures never grant skills, buffs or tracking.
class SwgxrRanger {
 using Json=JSONSerializationType;
 static std::string id(SceneObject* o){return o?std::to_string(o->getObjectID()):"0";}
 static Json position(SceneObject* o){auto p=o->getWorldPosition();return Json::array({p.getX(),p.getZ(),p.getY()});}
 static bool near(CreatureObject* c,CreatureObject* t,float range){return t && t->getZone()==c->getZone() && t->getParentID()==c->getParentID() && c->isInRange(t,range) && CollisionManager::checkLineOfSight(c,t);}
 static bool rescueTarget(CreatureObject* c,CreatureObject* t){if(!c->getPlayerObject()->hasAbility("rescue") || !t || !t->isAiAgent() || t->isPet() || t->isDead() || t->isIncapacitated() || !t->isInCombat() || !t->isAttackableBy(c) || !near(c,t,32) || !c->isGrouped())return false;auto defender=t->getMainDefender();return defender && defender->isPlayerCreature() && defender!=c && defender->asCreatureObject()->getGroup()==c->getGroup();}
 static bool validConceal(CreatureObject* c){auto b=c->getBuff(STRING_HASHCODE("skill_buff_mask_scent"));return b && b->getTimeLeft()>0 && c->getZone() && static_cast<ConcealBuff*>(b)->getPlanetName()==c->getZone()->getZoneName();}
 static Json concealState(CreatureObject* c){auto b=c->getBuff(STRING_HASHCODE("skill_buff_mask_scent"));return {{"active",validConceal(c)},{"power",c->getSkillModFromBuffs("private_conceal")},{"remaining_seconds",b?b->getTimeLeft():0.f},{"zone",b?std::string(static_cast<ConcealBuff*>(b)->getPlanetName().toCharArray()):""}};}
public:
 static bool action(const std::string& v){return v=="ranger_status" || v=="conceal" || v=="rescue" || v=="area_track";}
 static Json status(CreatureObject* c){
  auto ghost=c->getPlayerObject();Json types=Json::array();if(c->hasSkill("outdoors_ranger_novice")){types.push_back("animal");if(c->hasSkill("outdoors_ranger_harvest_02"))types.push_back("npc");if(c->hasSkill("outdoors_ranger_harvest_04"))types.push_back("player");}
  Json out={{"commands",Json::array()},{"camouflage",c->getSkillMod("camouflage")},{"rescue_mod",c->getSkillMod("rescue")},{"rescue_range_m",32},{"rescue_available",ghost->hasAbility("rescue") && c->isGrouped()},{"area_track_available",!types.empty() && c->getParentID()==0 && !c->isInCombat() && c->getPendingTask("areatrack")==nullptr},{"track_types",types},{"conceal",concealState(c)},{"kits",Json::array()},{"targets",Json::array()},{"tracking",Json::object()}};
  for(auto name:{"conceal","rescue","areatrack"})if(ghost->hasAbility(name))out["commands"].push_back(name);
  auto saved=ghost->getScreenPlayData("swgxr_ranger","tracking");if(!saved.isEmpty()){auto job=Json::parse(saved.toCharArray());if(job.value("state",std::string())=="pending" && c->getPendingTask("areatrack")==nullptr){job["state"]="failed";job["reason"]="native_tracking_interrupted";ghost->setScreenPlayData("swgxr_ranger","tracking",String(job.dump().c_str()));}out["tracking"]=job;}
  auto inventory=c->getSlottedObject("inventory");if(inventory){std::vector<SceneObject*> todo{inventory};std::set<uint64> seen;while(!todo.empty() && seen.size()<256){auto box=todo.back();todo.pop_back();if(!seen.insert(box->getObjectID()).second)continue;for(int i=0;i<box->getContainerObjectsSize();++i){auto o=box->getContainerObject(i);if(o->isCamoKit()){auto kit=o.castTo<TangibleObject*>();auto data=dynamic_cast<CamoKitTemplate*>(kit->getObjectTemplate());if(data)out["kits"].push_back({{"id",id(kit)},{"charges",kit->getUseCount()},{"effective_zone",std::string(data->getEffectiveZone().toCharArray())},{"usable",kit->getUseCount()>0 && data->getEffectiveZone()==c->getZone()->getZoneName()},{"tool_kind","camouflage"}});}else if(o->getContainerVolumeLimit()>0 && !o->isFactoryCrate() && !o->isCraftingTool())todo.push_back(o);}}}
  SortedVector<TreeEntry*> nearby(128,128);auto p=c->getWorldPosition();c->getZone()->getInRangeObjects(p.getX(),p.getZ(),p.getY(),32,&nearby,true);
  for(int i=0;i<nearby.size() && out["targets"].size()<64;++i){auto o=static_cast<SceneObject*>(nearby.get(i));if(o==c || !o->isCreatureObject())continue;auto t=o->asCreatureObject();Locker lock(t,c);bool player=t->isPlayerCreature() && near(c,t,3.5);bool rescue=rescueTarget(c,t);if(!player && !rescue)continue;out["targets"].push_back({{"id",id(t)},{"name",std::string(t->getDisplayedName().toCharArray())},{"template",std::string(t->getObjectTemplate()->getFullTemplateString().toCharArray())},{"position",position(t)},{"kind",player?"player":"rescue"},{"eligible",!t->isDead() && !t->isIncapacitated()},{"reason",""},{"radius",t->getTemplateRadius()},{"height",t->getHeight(false)},{"body_bounds",SwgxrPets::bodyBounds(t)}});}
  return out;
 }
 static void execute(CreatureObject* c,const Json& q,Json& mutation){
  mutation["request_id"]=q.at("request_id");auto verb=q.at("action").get<std::string>();auto controller=c->getZoneServer()->getObjectController();
  if(verb=="conceal"){
   auto kit=c->getZoneServer()->getObject(std::stoull(q.at("item_id").get<std::string>())).castTo<TangibleObject*>();if(!kit || !kit->isCamoKit() || !SwgxrEquipment::inInventory(kit,c) || kit->getUseCount()<1)throw std::runtime_error("owned_camouflage_kit_required");
   auto data=dynamic_cast<CamoKitTemplate*>(kit->getObjectTemplate());if(!data || data->getEffectiveZone()!=c->getZone()->getZoneName())throw std::runtime_error("camouflage_kit_wrong_planet");
   auto target=q.contains("target_id")?c->getZoneServer()->getObject(std::stoull(q.at("target_id").get<std::string>())).castTo<CreatureObject*>():ManagedReference<CreatureObject*>(c);if(!target || !target->isPlayerCreature() || target->isDead() || target->isIncapacitated() || target->isInCombat() || !near(c,target,3.5))throw std::runtime_error("nearby_living_player_required");Locker lock(target,c);
   if(c->isInCombat() || validConceal(target))throw std::runtime_error("target_in_combat_or_already_concealed");
   if(target!=c){auto h=q.at("hand_position");Vector3 point(h[0].get<float>(),h[2].get<float>(),h[1].get<float>());if(!SwgxrPets::touches(c,target,point))throw std::runtime_error("touch_player_to_apply_camouflage");}
   if(target->hasBuff(STRING_HASHCODE("skill_buff_mask_scent_self")))throw std::runtime_error("remove_mask_scent_before_camouflage");if(!target->checkCooldownRecovery("skill_buff_mask_scent_self"))throw std::runtime_error("camouflage_recovery_cooldown");
   auto cmd=controller->getQueueCommand("conceal");auto conceal=dynamic_cast<const ConcealCommand*>(cmd);if(!conceal)throw std::runtime_error("native_conceal_unavailable");if(!cmd->checkStateMask(c) || !cmd->checkInvalidLocomotions(c))throw std::runtime_error("native_conceal_invalid_state");if(conceal->checkHostileInRange(c->getZone(),target))throw std::runtime_error("hostile_within_32m_prevents_camouflage");// The original zone transition retains foreign-planet ConcealBuff objects.
   // Replace stale protection only after every non-mutating precondition passes.
   if(target->hasBuff(STRING_HASHCODE("skill_buff_mask_scent")))target->removeBuff(STRING_HASHCODE("skill_buff_mask_scent"));
   int before=kit->getUseCount();if(!cmd || cmd->doQueueCommand(c,target->getObjectID(),UnicodeString(String(id(kit).c_str())))!=QueueCommand::SUCCESS || !target->hasBuff(STRING_HASHCODE("skill_buff_mask_scent")))throw std::runtime_error("native_conceal_rejected");if(kit->getUseCount()!=before-1)throw std::runtime_error("native_camouflage_charge_mismatch");mutation["item_id"]=id(kit);mutation["target_id"]=id(target);mutation["charges_consumed"]=1;mutation["charges_remaining"]=kit->getUseCount();mutation["conceal"]=concealState(target);
  }else if(verb=="rescue"){
   auto t=c->getZoneServer()->getObject(std::stoull(q.at("target_id").get<std::string>())).castTo<CreatureObject*>();if(!t)throw std::runtime_error("rescue_enemy_required");Locker lock(t,c);if(!rescueTarget(c,t))throw std::runtime_error("original_rescue_target_or_skill_required");bool alreadyTaunted=t->getThreatMap()->hasState(ThreatStates::TAUNTED);auto cmd=controller->getQueueCommand("rescue");if(!cmd || cmd->doQueueCommand(c,t->getObjectID(),UnicodeString())!=QueueCommand::SUCCESS)throw std::runtime_error("native_rescue_rejected");mutation["target_id"]=id(t);mutation["rescued"]=!alreadyTaunted && t->getThreatMap()->hasState(ThreatStates::TAUNTED) && t->getThreatMap()->getHighestThreatAttacker()==c;
  }else if(verb=="area_track"){
   auto type=q.at("track_type").get<std::string>();int index=type=="animal"?0:type=="npc"?1:2;if(!c->hasSkill("outdoors_ranger_novice") || (index>=1 && !c->hasSkill("outdoors_ranger_harvest_02")) || (index==2 && !c->hasSkill("outdoors_ranger_harvest_04")) || c->isInCombat() || c->getParentID()!=0 || c->getPendingTask("areatrack")!=nullptr)throw std::runtime_error("native_area_track_unavailable");
   auto cmd=controller->getQueueCommand("areatrack");if(!cmd || cmd->doQueueCommand(c,0,UnicodeString())!=QueueCommand::SUCCESS)throw std::runtime_error("native_area_track_rejected");auto ghost=c->getPlayerObject();auto box=ghost->getSuiBoxFromWindowType(SuiWindowType::RANGER_TRACK_OPTIONS);if(!box)throw std::runtime_error("native_track_selection_unavailable");Vector<UnicodeString> args;args.add(UnicodeString(String::valueOf(index)));AreaTrackSuiCallback callback(c->getZoneServer(),"AreaTrack",String(q.at("request_id").get<std::string>().c_str()));callback.run(c,box,0,&args);ghost->removeSuiBox(box->getBoxID());if(c->getPendingTask("areatrack")==nullptr)throw std::runtime_error("native_area_track_not_started");Json job={{"request_id",q.at("request_id")},{"state","pending"},{"track_type",type},{"duration_seconds",6},{"results",Json::array()}};ghost->setScreenPlayData("swgxr_ranger","tracking",String(job.dump().c_str()));mutation["pending"]=true;
  }else throw std::runtime_error("unsupported_ranger_action");
 }
};
#endif
